import { App, FrontMatterCache, Notice, TAbstractFile, TFile } from "obsidian";
import { Intent, NewNoteProperties, } from ".";
import { 
  Template, 
} from "../templates";
import { 
  getRelativePath,
  TemplateVariable, 
  TemplateVariableType, 
  variableProviderVariableParsers,
} from "../variables";

